 function paintStats(){const d=licenseMeta.dashboard;stats.replaceChildren();for(const[key,label,state]of [['disponibles','Disponibles','disponible'],['reservadas','Reservadas','reservada'],['activas','Activas','activa'],['por_vencer','Por vencer','por_vencer'],['vencidas','Vencidas','vencida'],['renovaciones','Renovaciones realizadas','renovada']]){
  const card=button('',()=>{if(key==='renovaciones')licenseState.tab='historial';else{licenseState.tab='inventario';licenseState.state=state;}paint();},'license-stat');card.dataset.state=state;card.append(el('strong',String(d[key])),el('span',label));stats.append(card);}}
